// spi_monitor.sv - generated by uvm_full_tb_generator.py, filled in with SPI protocol logic
//   One item per CS_n frame; MOSI and MISO sampled on SCLK rising edges (mode 0).
//   Also checks that SCLK does not toggle while CS_n is high.
class spi_monitor extends uvm_monitor;
virtual spi_if vif;
uvm_analysis_port #(spi_item) ap;
int unsigned frame_count;
`uvm_component_utils(spi_monitor)
function new(string n,uvm_component p); super.new(n,p); ap=new("ap",this); endfunction

function void build_phase(uvm_phase phase);
  super.build_phase(phase);
  if (!uvm_config_db#(virtual spi_if)::get(this, "", "spi_vif", vif))
    `uvm_fatal("NOVIF", "spi_vif not set in uvm_config_db")
endfunction

task run_phase(uvm_phase phase);
  wait (vif.rst_n === 1'b1);
  fork check_idle(); join_none
  forever begin
    spi_item tr;
    bit [7:0] mo, mi;
    int nbit = 0;
    @(negedge vif.spi_cs_no);
    tr = spi_item::type_id::create("tr");
    tr.frame_no = frame_count++;
    forever begin
      @(posedge vif.spi_sclk_o or posedge vif.spi_cs_no);
      if (vif.spi_cs_no) break;
      mo = {mo[6:0], vif.spi_mosi_o};
      mi = {mi[6:0], vif.spi_miso_i};
      if (++nbit == 8) begin
        tr.mosi_bytes.push_back(mo);
        tr.miso_bytes.push_back(mi);
        nbit = 0;
      end
    end
    `uvm_info("SPI_MON", tr.convert2string(), UVM_MEDIUM)
    ap.write(tr);
  end
endtask

task check_idle();
  forever begin
    @(posedge vif.spi_sclk_o);
    if (vif.spi_cs_no === 1'b1) `uvm_error("SPI_MON", "SCLK toggled while CS_n is high")
  end
endtask
endclass
